@Path("/resolveSessions") @POST @Consumes(MediaType.APPLICATION_JSON) @Produces(MediaType.APPLICATION_JSON) 
public Response resolveSessions(RulePolicyRepresentation policy) {
    try {
        return Response.ok(getContainer(policy).getKieSessionNamesInKieBase(policy.getModuleName())).build();
    } catch (RuntimeException e) {
        return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity("Error resolving sessions: " + e.getMessage()).build();
    }
}
